source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    if all(len(set(row)) == 1 for row in grid):
        values = [row[0] for row in grid]
        runs = []
        start = None
        for i, v in enumerate(values + [0]):
            if i < h and v != 0 and start is None:
                start = i
            elif (i == h or v == 0) and start is not None:
                runs.append((start, i, values[start:i]))
                start = None
        if runs:
            start, end, seq = max(runs, key=lambda item: item[1] - item[0])
            period = next(p for p in range(1, len(seq) + 1)
                          if all(seq[i] == seq[i % p] for i in range(len(seq))))
            pattern = seq[:period]
            return [[pattern[(r - start) % period]] * w for r in range(h)]

    n = h
    candidates = []
    for kind in (0, 1):
        known = {}
        valid = True
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v == 0:
                    continue
                k = (c - r) % n if kind == 0 else (r + c) % n
                if k in known and known[k] != v:
                    valid = False
                    break
                known[k] = v
            if not valid:
                break
        if valid:
            candidates.append((len(known), kind, known))
    if candidates:
        _, kind, known = max(candidates)
        pattern = [known.get(k, 0) for k in range(n)]
        return [[pattern[(c - r) % n if kind == 0 else (r + c) % n]
                 for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
'''
